  "安装 frpc（frp 内网穿透客户端）内核：可在线下载官方版本自动安装，网络受限时改用离线上传官方 .tar.gz 包。安装前请确认服务器端 frps 与客户端版本兼容。": "安裝 frpc（frp 內網穿透客戶端）核心：可線上下載官方版本自動安裝，網路受限時改用離線上傳官方 .tar.gz 包。安裝前請確認伺服器端 frps 與客戶端版本相容。",
  "安装/升级时检测并复用上一版本数据，防止新建覆盖：安装与升级预处理检查数据目录（@appdata/TunHook）与配置目录（@appconf/TunHook）是否已有数据，齐全则直接复用，部分缺失只补迁移缺失项，迁移目标已存在则跳过，绝不新建默认数据覆盖已有数据": "安裝/升級時檢測並複用上一版本資料，防止新建覆蓋：安裝與升級預處理檢查資料目錄（@appdata/TunHook）與配置目錄（@appconf/TunHook）是否已有資料，齊全則直接複用，部分缺失只補遷移缺失項，遷移目標已存在則跳過，絕不新建預設資料覆蓋已有資料",
  "安装覆盖与升级共用同一套旧数据全位置迁移逻辑，覆盖安装同样不丢数据；修复卸载「保留数据」时数据库备份/恢复路径（数据库位于 @appdata/db/ 子目录）": "安裝覆蓋與升級共用同一套舊資料全位置遷移邏輯，覆蓋安裝同樣不丟資料；修復解除安裝「保留資料」時資料庫備份/恢復路徑（資料庫位於 @appdata/db/ 子目錄）",
