  "超时": "超時",
  "超时（秒）": "超時（秒）",
  "彻底修复 TCP 打洞通道持续满载 CPU（每条启用中的通道约吃掉一个核）：上一版把「清除连接读超时」放在了 client.Do() 之后，而 Do 的等待由第三方 STUN 库自身的重传序列驱动、可能远超探测超时——Do 不返回则清除永不执行，连接长期停留在「读超时已过期」状态，库的常驻读循环对读错误既不退出也不退让，于是全速空转并连带拉满 GC（因 Read 属系统调用，表现为系统态高企）。本版改为连接全程不设读超时、探测超时由 select 兜底，从结构上消除该状态": "徹底修復 TCP 打洞通道持續滿載 CPU（每條啟用中的通道約吃掉一個核）：上一版把「清除連線讀超時」放在了 client.Do() 之後，而 Do 的等待由第三方 STUN 庫自身的重傳序列驅動、可能遠超探測超時——Do 不返回則清除永不執行，連線長期停留在「讀超時已過期」狀態，庫的常駐讀迴圈對讀錯誤既不退出也不退讓，於是全速空轉並連帶拉滿 GC（因 Read 屬系統呼叫，表現為系統態高企）。本版改為連線全程不設讀超時、探測超時由 select 兜底，從結構上消除該狀態",
  "彻底修复 TCP 打洞通道满载 CPU 的根因：除读超时外，公网 STUN 服务器/NAT 主动断开空闲保活连接时，第三方 STUN 库的常驻读循环会因反复读到 EOF/reset 而全速空转（这才是真实环境启动即阵发性满载、而本机难以复现的触发路径）。本版彻底弃用该库的 Client，改在裸连接上手工收发 STUN 事务，空闲时无后台读循环、连接断开即立即重连，从结构上消除忙转": "徹底修復 TCP 打洞通道滿載 CPU 的根因：除讀超時外，公網 STUN 伺服器/NAT 主動斷開空閒保活連線時，第三方 STUN 庫的常駐讀迴圈會因反覆讀到 EOF/reset 而全速空轉（這才是真實環境啟動即陣發性滿載、而本機難以復現的觸發路徑）。本版徹底棄用該庫的 Client，改在裸連線上手工收發 STUN 事務，空閒時無後臺讀迴圈、連線斷開即立即重連，從結構上消除忙轉",
  "成功": "成功",
