  "端口扫描新增域名目标：输入域名后自动解析 IPv4 地址，仅解析出一个地址时直接开始扫描，多个地址时在输入框下方列出全部 IP 由用户选择（点击即按当前动作执行「扫描端口」/「扫描IP」，并可随时切换地址重扫）；新增 /api/ports/resolve 解析接口（多公共 DNS 兜底、地址去重、兼容误粘贴完整 URL）": "埠掃描新增域名目標：輸入域名後自動解析 IPv4 地址，僅解析出一個地址時直接開始掃描，多個地址時在輸入框下方列出全部 IP 由使用者選擇（點選即按當前動作執行「掃描埠」/「掃描IP」，並可隨時切換地址重掃）；新增 /api/ports/resolve 解析介面（多公共 DNS 兜底、地址去重、相容誤貼上完整 URL）",
