  "端口转发通道表单的「绑定域名」同步改造为「域名选择 + 主机记录」（与上一版 MEFrp / LoliaFrp 隧道一致）：域名从「域名解析」模块已有域名中下拉（跨账户聚合、优先展示已解析到所选 Frps 服务器 IP 的域名、未解析的标注「暂未解析」但同样可选），主机记录可选 @（主域名）或子域名（填前缀并实时显示完整域名）；新增「自定义域名」选项，选中后就地变为手动输入完整域名的输入框": "埠轉發通道表單的「繫結域名」同步改造為「域名選擇 + 主機記錄」（與上一版 MEFrp / LoliaFrp 隧道一致）：域名從「域名解析」模組已有域名中下拉（跨賬戶聚合、優先展示已解析到所選 Frps 伺服器 IP 的域名、未解析的標註「暫未解析」但同樣可選），主機記錄可選 @（主域名）或子域名（填字首並即時顯示完整域名）；新增「自定義域名」選項，選中後就地變為手動輸入完整域名的輸入框",
