  "能力边界：Cloudflare Tunnel 只发布 HTTP/HTTPS 域名（走 443，无端口号概念），UDP 不支持；\n      TCP/SSH/RDP 类服务需要访问方本地安装 cloudflared 才能连接。\n      需要 TCP/UDP 任意端口映射，请继续用「FRPC」或「MEFrp」。\n      Token 托管与 API 全托管需自有域名并托管在 Cloudflare，且大陆访问通常绕道境外节点，延迟偏高，适合 Webhook 回调与低频网页访问。": "能力邊界：Cloudflare Tunnel 只發布 HTTP/HTTPS 域名（走 443，無埠號概念），UDP 不支援；\n      TCP/SSH/RDP 類服務需要訪問方本地安裝 cloudflared 才能連線。\n      需要 TCP/UDP 任意埠對映，請繼續用「FRPC」或「MEFrp」。\n      Token 託管與 API 全託管需自有域名並託管在 Cloudflare，且大陸訪問通常繞道境外節點，延遲偏高，適合 Webhook 回撥與低頻網頁訪問。",
