  "系统设置侧栏子分区顺序调整，并删除与「系统日志」页重复的「日志管理」分区；把设置页子分区清单提为唯一来源，侧栏子菜单与页头副标题由同一份清单生成（此前两份手工清单已漂移、副标题漏两项）；主侧栏标签顺序调整": "系統設定側欄子分割槽順序調整，並刪除與「系統日誌」頁重複的「日誌管理」分割槽；把設定頁子分割槽清單提為唯一來源，側欄子選單與頁頭副標題由同一份清單生成（此前兩份手工清單已漂移、副標題漏兩項）；主側欄標籤順序調整",
  "系统设置分区": "系統設定分割槽",
  "系统设置新增模块管理：可关闭暂不使用的模块（STUN/内网穿透/端口转发/Webhook/MEFrp/Cloudflare Tunnel/端口扫描），关闭后导航入口隐藏、直接访问其页面被拦下、仪表盘对应卡片一并隐藏，已启动的隧道与转发规则照常工作": "系統設定新增模組管理：可關閉暫不使用的模組（STUN/內網穿透/埠轉發/Webhook/MEFrp/Cloudflare Tunnel/埠掃描），關閉後導航入口隱藏、直接訪問其頁面被攔下、儀表盤對應卡片一併隱藏，已啟動的隧道與轉發規則照常工作",
  "系统自动生成的 Cloudflare 隧道回源转发，请到「Cloudflare Tunnel」页面管理": "系統自動生成的 Cloudflare 隧道回源轉發，請到「Cloudflare Tunnel」頁面管理",
  "系统自动生成的 STUN 打洞转发，请到「STUN」页面管理": "系統自動生成的 STUN 打洞轉發，請到「STUN」頁面管理",
  "系统自动生成的内网穿透转发，请到「代理列表」页面管理": "系統自動生成的內網穿透轉發，請到「代理列表」頁面管理",
  "细节改进：密码验证页文案精简；域名模式访问接口地址不再携带端口、统一经 frpc 域名代理；打开密码验证页记录访问日志；系统设置「证书管理」标签精简为 TLS": "細節改進：密碼驗證頁文案精簡；域名模式訪問介面地址不再攜帶埠、統一經 frpc 域名代理；開啟密碼驗證頁記錄訪問日誌；系統設定「證書管理」標籤精簡為 TLS",
