  "选择 DNS 服务商账户后，可查看其名下域名并管理解析记录（A / AAAA / CNAME / TXT 等）；支持动态解析与 TLS 证书自动续签。账户请在「DNS 账号」中添加。": "選擇 DNS 服務商賬戶後，可檢視其名下域名並管理解析記錄（A / AAAA / CNAME / TXT 等）；支援動態解析與 TLS 證書自動續簽。賬戶請在「DNS 賬號」中新增。",
