  "选择客户端上报与通道访问使用的系统地址方式：使用 IP（本机地址），可选域名。": "選擇客戶端上報與通道訪問使用的系統地址方式：使用 IP（本機地址），可選域名。",
  "选择日志模块与导出格式（TXT/JSON/CSV）后下载当前缓冲中的日志": "選擇日誌模組與匯出格式（TXT/JSON/CSV）後下載當前緩衝中的日誌",
