  "选择域名后，可把该节点的连接地址写进解析": "選擇域名後，可把該節點的連線地址寫進解析",
  "选择域名后，可把该隧道的节点地址写进解析": "選擇域名後，可把該隧道的節點地址寫進解析",
  "选择域名后，隧道创建成功即自动写入解析": "選擇域名後，隧道建立成功即自動寫入解析",
