  "页面不存在": "頁面不存在",
  "页面无法显示？在新标签页打开 ↗": "頁面無法顯示？在新標籤頁開啟 ↗",
  "一次映射，全网可达。任何外网服务器都能主动连接内网主机。": "一次對映，全網可達。任何外網伺服器都能主動連線內網主機。",
  "一键启动 / 停止，实时查看 PID 与已加载隧道数量": "一鍵啟動 / 停止，即時檢視 PID 與已載入隧道數量",
  "一键扫描": "一鍵掃描",
  "仪表盘": "儀表盤",
  "仪表盘 KPI 概览移动端改为两列紧凑布局（6 张卡 3 行），并隐藏进程协程数、TCP/UDP 明细、转发总数等次要信息": "儀表盤 KPI 概覽移動端改為兩列緊湊佈局（6 張卡 3 行），並隱藏程序協程數、TCP/UDP 明細、轉發總數等次要資訊",
  "仪表盘「系统信息」卡新增设备名称、系统版本、系统时间：设备时间按服务端时间校正后每秒走字，远程访问时显示的仍是设备本地时间（不受浏览器时区影响）": "儀表盤「系統資訊」卡新增裝置名稱、系統版本、系統時間：裝置時間按服務端時間校正後每秒走字，遠端訪問時顯示的仍是裝置本地時間（不受瀏覽器時區影響）",
  "仪表盘「frp 服务器」卡改版为客户端/服务端视角：客户端版本、客户端状态、服务端地址、服务端状态、网络延迟、通道数量、通道在线率": "儀表盤「frp 伺服器」卡改版為客戶端/服務端視角：客戶端版本、客戶端狀態、服務端地址、服務端狀態、網路延遲、通道數量、通道線上率",
  "仪表盘布局自定义：KPI 概览与卡片可拖动排序、收起恢复（收起项在同组底部列出），卡片内各行的显隐与顺序也可单独编辑（齿轮或右键卡片），带实时布局预览；KPI 最多显示 8 项，支持一键恢复默认布局，改动即时保存且随备份保留": "儀表盤佈局自定義：KPI 概覽與卡片可拖動排序、收起恢復（收起項在同組底部列出），卡片內各行的顯隱與順序也可單獨編輯（齒輪或右鍵卡片），帶即時佈局預覽；KPI 最多顯示 8 項，支援一鍵恢復預設佈局，改動即時儲存且隨備份保留",
  "仪表盘流量统计图表的原始采样数据保留天数": "儀表盤流量統計圖表的原始取樣資料保留天數",
  "仪表盘全新改版：KPI 概览条、系统/隧道/转发实时速率图、连接状态网格展示": "儀表盤全新改版：KPI 概覽條、系統/隧道/轉發即時速率圖、連線狀態網格展示",
  "仪表盘上该模块的卡片会一并隐藏": "儀表盤上該模組的卡片會一併隱藏",
  "仪表盘网络信息增强：将「本地地址」拆分为 IPv4/IPv6 两行分别显示，原生读取网卡信息按优先级筛选（优先全局单播、其次 ULA），过滤回环/链路本地/组播等无效地址": "儀表盤網路資訊增強：將「本地地址」拆分為 IPv4/IPv6 兩行分別顯示，原生讀取網絡卡資訊按優先順序篩選（優先全域性單播、其次 ULA），過濾迴環/鏈路本地/組播等無效地址",
  "仪表盘新增 Webhook 状态卡（通道数/最近活动/重定向次数/成功率）与「通道导航」「服务状态」页头快捷入口": "儀表盤新增 Webhook 狀態卡（通道數/最近活動/重定向次數/成功率）與「通道導航」「服務狀態」頁頭快捷入口",
  "仪表盘与系统设置必须常驻：模块管理位于系统设置内，若允许关闭将再也无法开启任何模块。": "儀表盤與系統設定必須常駐：模組管理位於系統設定內，若允許關閉將再也無法開啟任何模組。",
