  "IP 过滤（拦截）重构升级：新增白名单/黑名单模式（白名单仅放行名单内地址，黑名单默认拦截名单内地址）、局域网地址放行开关（默认开启，关闭前弹出风险提示）、按归属地（国家/省/市/运营商/公有云）直接加入黑白名单、白名单防误锁保护、本机回环固定放行、默认关闭": "IP 過濾（攔截）重構升級：新增白名單/黑名單模式（白名單僅放行名單內地址，黑名單預設攔截名單內地址）、區域網地址放行開關（預設開啟，關閉前彈出風險提示）、按歸屬地（國家/省/市/運營商/公有云）直接加入黑白名單、白名單防誤鎖保護、本機迴環固定放行、預設關閉",
