  "Lolia 云端": "Lolia 雲端",
  "LoliaFrp 不支持修改节点、类型、远程端口与隧道名称，如需更换请删除后重建。": "LoliaFrp 不支援修改節點、型別、遠端埠與隧道名稱，如需更換請刪除後重建。",
  "LoliaFrp 控制台": "LoliaFrp 控制檯",
  "LoliaFrp 洛链映射 · OAuth 授权接入（lolia.link）": "LoliaFrp 洛鏈對映 · OAuth 授權接入（lolia.link）",
  "LoliaFrp 授权成功": "LoliaFrp 授權成功",
  "LoliaFrp 隧道已停止": "LoliaFrp 隧道已停止",
  "LoliaFrp 账户下暂无隧道": "LoliaFrp 賬戶下暫無隧道",
  "LoliaFrp 账户下暂无隧道，请前往控制台创建": "LoliaFrp 賬戶下暫無隧道，請前往控制檯建立",
  "MAC 地址": "MAC 地址",
  "MAC 格式应为 AA:BB:CC:DD:EE:FF（也支持 - 分隔或无分隔）": "MAC 格式應為 AA:BB:CC:DD:EE:FF（也支援 - 分隔或無分隔）",
  "ME Frp 幻缘映射 · 稳定高效的内网穿透利器": "ME Frp 幻緣對映 · 穩定高效的內網穿透利器",
  "MEFrp / LoliaFrp 隧道「绑定域名」改造为「域名选择 + 主机记录」：域名从「域名解析」模块已有域名中下拉选择，主机记录可选 @（主域名）或子域名（填前缀并实时显示完整域名），不再手输完整域名；隧道创建成功后自动把节点连接地址解析到该域名（解析出 IPv4 写 A 记录，解析不到才退化为 CNAME），删除隧道时同步删除指向该节点的解析记录（只删「主机记录 + 类型 + 值」都对得上的那条，避免误删手工改过的记录）；编辑弹窗提供「写入解析」按钮，并显示解析目标（记录类型 + 实际写入的地址）。LoliaFrp 的候选域名取「域名解析里的域名 ∩ 已在 Lolia 完成归属验证的域名」，避免选出建不成隧道的域名。新增跨账户聚合域名接口与 MEFrp 节点连接地址接口支撑该功能": "MEFrp / LoliaFrp 隧道「繫結域名」改造為「域名選擇 + 主機記錄」：域名從「域名解析」模組已有域名中下拉選擇，主機記錄可選 @（主域名）或子域名（填字首並即時顯示完整域名），不再手輸完整域名；隧道建立成功後自動把節點連線地址解析到該域名（解析出 IPv4 寫 A 記錄，解析不到才退化為 CNAME），刪除隧道時同步刪除指向該節點的解析記錄（只刪「主機記錄 + 型別 + 值」都對得上的那條，避免誤刪手工改過的記錄）；編輯彈窗提供「寫入解析」按鈕，並顯示解析目標（記錄型別 + 實際寫入的地址）。LoliaFrp 的候選域名取「域名解析裡的域名 ∩ 已在 Lolia 完成歸屬驗證的域名」，避免選出建不成隧道的域名。新增跨賬戶聚合域名介面與 MEFrp 節點連線地址介面支撐該功能",
  "MEFrp 不支持修改隧道节点，如需更换节点请删除该隧道后按新节点重建": "MEFrp 不支援修改隧道節點，如需更換節點請刪除該隧道後按新節點重建",
  "MEFrp 电源按钮状态灯语义：隧道在线=绿色（点击强制下线）、离线=红色（点击启用隧道），上下线一键闭环": "MEFrp 電源按鈕狀態燈語義：隧道線上=綠色（點選強制下線）、離線=紅色（點選啟用隧道），上下線一鍵閉環",
  "MEFrp 节点权限控制：「无权限」筛选改为筛掉无权限节点；点击无权限节点（如正式用户点 VIP 节点）提示「无权使用此节点，请开通 VIP 会员」": "MEFrp 節點許可權控制：「無許可權」篩選改為篩掉無許可權節點；點選無許可權節點（如正式使用者點 VIP 節點）提示「無權使用此節點，請開通 VIP 會員」",
  "MEFrp 界面改进：账户卡信息合并为一行；签到/权益抽取改为竖排；移动端适配（账户信息每项一行）；frpc 运行日志常驻显示并每 15 秒自动刷新（移除查看/隐藏日志按钮）；页面副标题更新": "MEFrp 介面改進：賬戶卡資訊合併為一行；簽到/權益抽取改為豎排；移動端適配（賬戶資訊每項一行）；frpc 執行日誌常駐顯示並每 15 秒自動重新整理（移除檢視/隱藏日誌按鈕）；頁面副標題更新",
  "MEFrp 密钥已保存": "MEFrp 金鑰已儲存",
  "MEFrp 启用/强制下线本地同步：点启用时云端已禁用的隧道自动启用后再拉起、本地 frpc 已在运行自动重启并保留其他隧道；强制下线时云端踢下线并同时从本地 frpc 移除该隧道（移出自启列表、按剩余隧道重启或停止进程），下线保持离线不自动回连": "MEFrp 啟用/強制下線本地同步：點啟用時雲端已停用的隧道自動啟用後再拉起、本地 frpc 已在執行自動重啟並保留其他隧道；強制下線時雲端踢下線並同時從本地 frpc 移除該隧道（移出自啟列表、按剩餘隧道重啟或停止程序），下線保持離線不自動回連",
  "MEFrp 权益抽取流量单位显示修复：按数值自动换算正确单位（GB/MB），不再一律按 MB 展示": "MEFrp 權益抽取流量單位顯示修復：按數值自動換算正確單位（GB/MB），不再一律按 MB 展示",
  "MEFrp 权益抽取修复（只能抽 9 次问题）、人机验证窗口与本地工具栏布局优化、图标风格统一": "MEFrp 權益抽取修復（只能抽 9 次問題）、人機驗證視窗與本地工具欄佈局最佳化、圖示風格統一",
  "MEFrp 权益抽取状态完善：剩余次数 x/10 展示；次数用完后显示「已抽取」；按天记录当日已抽完状态（跨天自动重置）": "MEFrp 權益抽取狀態完善：剩餘次數 x/10 展示；次數用完後顯示「已抽取」；按天記錄當日已抽完狀態（跨天自動重置）",
