  "YUNXI 的赞赏码": "YUNXI 的贊賞碼",
  "修复 frpc 日志查看接口带写副作用：LogTailFor 此前会按配置的日志保留行数顺带裁剪日志（即重写整个文件），上一版新增的登录看门狗每 2 秒调用一次，使只读接口变成高频写盘。现将裁剪与读取解耦：LogTailFor 改为纯读，裁剪收敛到新的唯一入口 TrimLogs，由看门狗按 60 秒间隔节流执行，防止日志无限增长的原有能力不变；仅当 LogEntries > 0 时才会触发裁剪，默认 0（不限制）不受影响": "修正 frpc 日誌檢視 API 帶寫入副作用：LogTailFor 先前會依設定的日誌保留行數順帶裁剪日誌（即重寫整個檔案）。上一版新增的登入看門狗每 2 秒呼叫一次，使唯讀 API 變成高頻寫盤。現將裁剪與讀取解耦：LogTailFor 改為純讀，裁剪收斂到新的唯一入口 TrimLogs，由看門狗以 60 秒間隔節流執行；防止日誌無限增長的原有能力不變。僅當 LogEntries > 0 時才會觸發裁剪，預設 0（不限制）不受影響。",
  "新增 frpc 登录看门狗，穿透断连后能自行恢复：按日志中最后一条登录结果判定，连续 10 次失败（约 20 秒）自动重启该实例并清零计数；进程重启后有 30 秒启动宽限期，避免旧日志残留触发连续重启。判定依据是登录日志而非管理 API——管理 API 只反映 frpc 进程存活，不反映隧道是否连通": "新增 frpc 登入看門狗，穿透斷線後可自行恢復：依日誌中最後一條登入結果判定，連續 10 次失敗（約 20 秒）自動重啟該實例並清零計數；程序重啟後有 30 秒啟動寬限期，避免舊日誌殘留觸發連續重啟。判定依據是登入日誌而非管理 API——管理 API 只反映 frpc 程序存活，不反映隧道是否連通。",
  "FRP 管理 API 查询失败不再静默丢弃：/api/frpc/conns 新增 failed 字段，返回查询失败的服务器及原因（无应答 / HTTP 状态码 / 响应解析失败），界面可区分「隧道断开」与「查不到状态」": "FRP 管理 API 查詢失敗不再靜默丟棄：/api/frpc/conns 新增 failed 欄位，回傳查詢失敗的伺服器及原因（無應答 / HTTP 狀態碼 / 回應解析失敗），介面可區分「隧道斷開」與「查不到狀態」。",
  "服务器状态新增 watchdog_fails 字段，展示连续登录失败次数，便于确认是否正在自动恢复": "伺服器狀態新增 watchdog_fails 欄位，顯示連續登入失敗次數，便於確認是否正在自動恢復。",
  "搜索更新日志": "搜尋更新日誌",
  "没有匹配的版本": "沒有符合的版本",
  "管理界面全站国际化：新增简体中文 / 繁体中文 / English / 日本語 四种语言，切换即时生效无需刷新；全部页面、弹窗、表单校验、Toast 与无障碍标签均已接入（3037 条词条）": "管理介面全站國際化：新增簡體中文 / 繁體中文 / English / 日本語 四種語言，切換即時生效無需重新整理；全部頁面、彈窗、表單驗證、Toast 與無障礙標籤均已接入（3037 條詞條）",
  "「关于」页更新日志支持版本目录与搜索：左侧版本列表可点击跳转并高亮当前版本，搜索框按版本号或条目内容过滤并高亮命中文字": "「關於」頁更新日誌支援版本目錄與搜尋：左側版本清單可點擊跳轉並高亮目前版本，搜尋框按版本號或條目內容過濾並高亮命中文字",
  "「关于」页新增「支持开发者」入口，点击弹出赞赏码；免责声明与开发者信息卡片等高，声明正文内部滚动且隐藏滚动条": "「關於」頁新增「支持開發者」入口，點擊彈出贊賞碼；免責聲明與開發者資訊卡片等高，聲明正文內部滾動且隱藏滾動條",
